function validate(points) {
  if (points.length !== 4) return 'Give exactly four points.';
  for (const p of points) {
    if (!Array.isArray(p) || p.length !== 2) return 'Each point is a pair [x, y].';
    if (p.some(v => !Number.isInteger(v) || v < -10000 || v > 10000)) return 'Each coordinate is a whole number from -10^4 to 10^4.';
  }
  return null;
}

