function validSquare(p1, p2, p3, p4) {
  const points = [p1, p2, p3, p4];
  const distances = [];
  for (let i = 0; i < 4; i++) {
    for (let j = i + 1; j < 4; j++) {
      const dx = points[i][0] - points[j][0];
      const dy = points[i][1] - points[j][1];
      distances.push(dx * dx + dy * dy);
    }
  }
  distances.sort((a, b) => a - b);

  const side = distances[0];
  const diagonal = distances[5];
  if (side === 0) {
    return false;
  }
  const equalSides = distances[1] === side && distances[2] === side && distances[3] === side;
  const equalDiagonals = distances[4] === diagonal;
  return equalSides && equalDiagonals && diagonal === 2 * side;
}

