function validSquare(p1, p2, p3, p4) {
  // Try every ordering a, b, c, d of the corners; walking a -> b and then turning
  // a quarter turn must reach c, and the same quarter turn from a must reach d.
  const pts = [p1, p2, p3, p4];
  const same = (u, v) => u[0] === v[0] && u[1] === v[1];
  for (let a = 0; a < 4; a++)
    for (let b = 0; b < 4; b++)
      for (let c = 0; c < 4; c++)
        for (let d = 0; d < 4; d++) {
          if (new Set([a, b, c, d]).size !== 4) continue;
          const vx = pts[b][0] - pts[a][0], vy = pts[b][1] - pts[a][1];
          if (vx === 0 && vy === 0) continue;
          const wx = -vy, wy = vx;
          if (same(pts[c], [pts[b][0] + wx, pts[b][1] + wy]) && same(pts[d], [pts[a][0] + wx, pts[a][1] + wy])) return true;
        }
  return false;
}

