function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const limit = size === 'large' ? 10000 : 4;
  const coord = () => pick(2 * limit + 1) - limit;
  const inside = p => Math.abs(p[0]) <= limit && Math.abs(p[1]) <= limit;
  const shuffle = list => {
    for (let i = list.length - 1; i > 0; i--) { const j = pick(i + 1); [list[i], list[j]] = [list[j], list[i]]; }
    return list;
  };
  for (;;) {
    const roll = rand();
    let points;
    if (roll < 0.25) {
      // Four independent random points (almost always not a square).
      points = [[coord(), coord()], [coord(), coord()], [coord(), coord()], [coord(), coord()]];
    } else if (roll < 0.35) {
      // Repeated points: a zero-length side must be rejected.
      const a = [coord(), coord()], b = [coord(), coord()];
      points = rand() < 0.5 ? [a, a.slice(), b, b.slice()] : [a, a.slice(), a.slice(), a.slice()];
    } else {
      // A real square from a corner a and edge vector v, possibly bent into a rhombus,
      // rectangle or nudged corner so that near misses appear.
      const a = [coord(), coord()];
      const v = [coord() >> (size === 'large' ? 1 : 0), coord() >> (size === 'large' ? 1 : 0)];
      let w = [-v[1], v[0]];
      const kind = rand();
      if (kind < 0.15) w = [w[0] * 2, w[1] * 2];
      else if (kind < 0.3) w = [v[1], v[0]];
      points = [a, [a[0] + v[0], a[1] + v[1]], [a[0] + v[0] + w[0], a[1] + v[1] + w[1]], [a[0] + w[0], a[1] + w[1]]];
      if (kind >= 0.3 && kind < 0.42) points[3][pick(2)] += rand() < 0.5 ? 1 : -1;
    }
    if (points.every(inside)) return shuffle(points);
  }
}
